import {useLocation} from '@github-ui/react-router'
import {sendStats} from '@github-ui/stats'
import {useClickAnalytics} from '@github-ui/use-analytics'
import React from 'react'

import {CoreSsoBanner} from './components/CoreSsoBanner'
import {ConfirmationDialog} from './components/dialog/ConfirmationDialog'
import {DEFAULT_COOKIE_EXPIRATION_DAYS} from './components/dialog/constants'
import {SlideDismiss} from './components/SlideDismiss'
import {SSOActionMenu} from './components/SSOActionMenu'
import {ANALYTICS_CATEGORY} from './constants'
import {storeDismissedOrgIds} from './cookie'
import type {GlobalSsoBannerProps} from './types'

export function GlobalSsoBanner({ssoOrgs, onConfirm}: GlobalSsoBannerProps) {
  const location = useLocation()
  const [bannerState, setBannerState] = React.useState<'visible' | 'hidden'>('visible')
  const [dialogIsOpen, setDialogIsOpen] = React.useState(false)
  const hasSentMetricRef = React.useRef(false)
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  React.useEffect(() => {
    if (!hasSentMetricRef.current && ssoOrgs.length > 0) {
      sendStats({
        incrementKey: 'GLOBAL_SSO_BANNER_DISPLAYED',
        requestUrl: window.location.href,
      })
      hasSentMetricRef.current = true
    }
  }, [ssoOrgs])

  if (ssoOrgs.length === 0) {
    return null
  }

  const dismissSsoOrganizations = (durationDays: number = DEFAULT_COOKIE_EXPIRATION_DAYS) => {
    setBannerState('hidden')
    storeDismissedOrgIds(ssoOrgs, durationDays)
  }

  // Hide the banner when the user clicks the close button
  const handleDismiss = () => {
    sendClickAnalyticsEvent({
      category: ANALYTICS_CATEGORY,
      action: 'click_dismiss_button',
      label: 'banner_dismissed',
    })

    setDialogIsOpen(true)
  }

  const handleDialogDismiss = (durationDays: number) => {
    onConfirm?.()
    dismissSsoOrganizations(durationDays)
    setDialogIsOpen(false)
  }

  return (
    <>
      <SlideDismiss hidden={bannerState !== 'visible'}>
        <CoreSsoBanner
          ssoOrgs={ssoOrgs}
          onDismiss={handleDismiss}
          primaryAction={<SSOActionMenu ssoOrgs={ssoOrgs} redirectLocation={location} />}
        />
      </SlideDismiss>

      <ConfirmationDialog
        isOpen={dialogIsOpen}
        onClose={() => setDialogIsOpen(false)}
        onConfirm={handleDialogDismiss}
        ssoOrgs={ssoOrgs}
      />
    </>
  )
}
